def esc(s):return str(s).replace('~','~0').replace('/','~1')
def differences(a,b,p=''):
 if type(a)!=type(b):return [p]
 if isinstance(a,dict):
  out=[]
  for k in sorted(set(a)|set(b)):
   q=p+'/'+esc(k)
   out += [q] if k not in a or k not in b else differences(a[k],b[k],q)
  return out
 if isinstance(a,list):
  out=[]
  for i in range(max(len(a),len(b))):
   q=p+'/'+str(i);out += [q] if i>=len(a) or i>=len(b) else differences(a[i],b[i],q)
  return out
 return [] if a==b else [p]
def pointer(doc,p):
 for k in p.strip('/').split('/'):doc=doc[int(k)] if isinstance(doc,list) else doc[k.replace('~1','/').replace('~0','~')]
 return doc
